/bin/bash -lc "python - <<'PY'
palettes={'light':('#FFFFFF','#17212B','#465563','#A31825','#176534','#805000','#505C68'),'dark':('#181C20','#F3F6F8','#B9C5D0','#FFB4B8','#8BE0A8','#FFD58A','#BAC5CF'),'light increased':('#FFFFFF','#000000','#283440','#7C0012','#004820','#603900','#303B46'),'dark increased':('#101214','#FFFFFF','#E3EAF0','#FFDADD','#C4F7D4','#FFE9BC','#E0E7ED')}
def lum(h):
 v=[int(h[i:i+2],16)/255 for i in (1,3,5)]
 v=[x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4 for x in v]
 return sum(x*y for x,y in zip(v,[.2126,.7152,.0722]))
for mode,colors in palettes.items():
 bg,*fg=colors
 print(mode, 'background',bg,[(c,round((max(lum(c),lum(bg))+.05)/(min(lum(c),lum(bg))+.05),2)) for c in fg])
PY"

